"""Render the verified campaign into a staging directory; never deploy here."""
from html import escape
import hashlib
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[4]
BENCH = ROOT / 'tests/benchmarks/robot_control'
PACKAGE = BENCH / 'publication/publication-preview-opus-cached-01'
OUT = ROOT / '.tmp/benchmark-website-20260924'
SITE = Path('O:/omnilink')
URL = '/benchmarks/robotics-control/index.html'
LABELS = {
    'omnilink_parser': 'OmniLink',
    'plain': 'Plain model loop',
    'langgraph': 'LangGraph',
    'lobster': 'Lobster SDK',
    'langgraph_parser': 'LangGraph + OmniLink command handling',
    'lobster_parser': 'Lobster SDK + OmniLink command handling',
}


def write(name, text):
    p = OUT / name
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')


def main():
    audit = json.loads((PACKAGE / 'ANTHROPIC_AUDIT.json').read_text())
    verification = json.loads((PACKAGE / 'OFFLINE_VERIFICATION.json').read_text())
    assert audit['complete'] and audit['observed'] == 198 and audit['journal_reconciles']
    assert verification['verified'] and not audit['verification']['accounting_mismatches']
    for line in (PACKAGE / 'SHA256SUMS.txt').read_text().splitlines():
        digest, name = line.split()
        assert hashlib.sha256((PACKAGE / name).read_bytes()).hexdigest() == digest
    scores = audit['summary']
    omni = scores['omnilink_parser']; plain = scores['plain']
    reduction = 100 * (1 - omni['usd_per_success'] / plain['usd_per_success'])
    assert omni['pass'] == 33 and round(reduction) == 45
    base = 'public/benchmarks/robotics-control/'
    for name in ('evidence.zip', 'development-history.zip', 'SHA256SUMS.txt',
                 'REPRODUCE.md', 'MATCHED_COMPARISON.md', 'ANTHROPIC_AUDIT.json',
                 'OFFLINE_VERIFICATION.json'):
        dest = OUT / base / name
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(PACKAGE / name, dest)
    shutil.copyfile(BENCH / 'SPEC.md', OUT / base / 'SPEC.md')
    public = {**audit, 'display_labels': LABELS,
              'public_cost_scope': 'Provider list-rate model costs, not invoice or total operating cost. Per-configuration costs exclude $0.006072 shared setup.',
              'reproduction_status': 'Offline verification passed. Fresh live reproduction requires the matching runtime/source release; availability has not been verified.'}
    write(base + 'results.json', json.dumps(public, indent=2) + '\n')

    section = f'''    <section class="robotics-benchmark wrap section" id="robotics-benchmark" aria-labelledby="benchmark-title">
      <div class="benchmark-heading"><div><p class="eyebrow">OmniLink benchmarks · Measured in OmniSim</p><h2 id="benchmark-title">Robot control.<br /><span>Measured, end to end.</span></h2></div><p>33 tasks. Three simulated robots in OmniSim. Six control configurations, tested with the same model and scored against measured robot behavior.</p></div>
      <div class="benchmark-kpis">
        <article><p class="benchmark-label">OmniLink task completion</p><p class="benchmark-number">33<span>/33</span></p><p>All tasks completed in this run.</p></article>
        <article><p class="benchmark-label">Lower model cost per successful task</p><p class="benchmark-number">{reduction:.0f}<span>%</span></p><p>Versus the tested plain model loop.</p></article>
        <article><p class="benchmark-label">Model cost per successful task</p><p class="benchmark-number benchmark-price">${omni['usd_per_success']:.5f}</p><p>OmniLink · plain loop: ${plain['usd_per_success']:.5f}</p></article>
      </div>
      <div class="benchmark-takeaway"><p><strong>Efficiency, with the full comparison in view.</strong> Four other configurations also completed 33/33 tasks; the plain loop completed 32/33. LangGraph and Lobster with OmniLink command handling matched completion at slightly lower model cost.</p><a class="button" href="{URL}">Explore the benchmarks <span aria-hidden="true">↗</span></a></div>
      <p class="benchmark-scope">Developer-authored development suite · One repeat per task · Opus 5.5, low effort, caching enabled · Simulation only, with assisted arm grasping. Model costs include failed attempts and exclude shared cache warm-up ($0.006072), subscriptions, hosting and local compute. This result does not establish a market-wide capability lead.</p>
      <p class="benchmark-scope">Full results, original evidence and offline verification are available. A fresh live reproduction requires the matching OmniSim runtime and source release; its public availability has not been verified.</p>
    </section>'''
    home = (SITE / 'index.html').read_text(encoding='utf-8')
    marker = '    <section class="cost-comparison' if '    <section class="cost-comparison' in home else '    <section class="robotics-benchmark'
    start = home.index(marker)
    end = home.index('    <section class="outcomes', start)
    home = home[:start] + section + '\n\n' + home[end:]
    if '/benchmarks/robotics-control/benchmark.css' not in home:
        home = home.replace('<link rel="stylesheet" href="/landing.css" />', '<link rel="stylesheet" href="/landing.css" />\n  <link rel="stylesheet" href="/benchmarks/robotics-control/benchmark.css" />')
    home = home.replace('<nav aria-label="Footer"><a href="/omnisim">', f'<nav aria-label="Footer"><a href="{URL}">Benchmarks</a><a href="/omnisim">')
    write('index.html', home)

    bars = []; table = []; paired = []
    for key, label in LABELS.items():
        s = scores[key]; highlight = ' is-omnisim' if key == 'omnilink_parser' else ''
        bars.append(f'<div class="bench-bar-row{highlight}"><div class="bench-bar-label"><span>{escape(label)}</span><strong>${s["usd_per_success"]:.5f}</strong></div><div class="bench-bar-track" aria-hidden="true"><div style="width:{100*s["usd_per_success"]/.030:.3f}%"></div></div></div>')
        table.append(f'<tr class="{highlight.strip()}" data-configuration="{key}"><th scope="row">{escape(label)}</th><td>{s["pass"]}/{s["episodes"]}</td><td>{s["fail"]}</td><td>{s["unsafe"]}</td><td>{s["model_calls"]}</td><td>${s["derived_usd"]:.6f}</td><td>${s["usd_per_success"]:.5f}</td></tr>')
    for key, c in audit['comparisons'].items():
        lo, hi = c['family_bootstrap_95']['cost_per_success_ratio']
        paired.append(f'<tr><th scope="row">{escape(LABELS[key])}</th><td>{c["point"]["success_difference_pp"]:+.2f} pp</td><td>{c["point"]["cost_per_success_ratio"]:.3f}</td><td>{lo:.3f}–{hi:.3f}</td></tr>')
    page = f'''<!doctype html>
<html lang="en" data-theme="dark"><head>
<meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" />
<title>OmniLink Robotics-Control Benchmarks</title>
<meta name="description" content="Inspect OmniLink robotics-control results in OmniSim: 33 tasks, six configurations, measured completion, model costs, full evidence and offline verification." />
<link rel="canonical" href="https://www.omnilink-agents.com{URL}" />
<meta property="og:title" content="OmniLink Robotics-Control Benchmarks" /><meta property="og:description" content="33 tasks. Six configurations. Measured completion and model costs, with every result available to inspect." />
<meta property="og:url" content="https://www.omnilink-agents.com{URL}" /><meta property="og:type" content="website" /><meta property="og:site_name" content="OmniLink" />
<meta property="og:image" content="https://www.omnilink-agents.com/branding/omnisim/warehouse_husky_hero.png" />
<meta name="twitter:card" content="summary_large_image" /><meta name="twitter:title" content="OmniLink Robotics-Control Benchmarks" /><meta name="twitter:description" content="Measured robotics-control results, full evidence and offline verification." /><meta name="twitter:image" content="https://www.omnilink-agents.com/branding/omnisim/warehouse_husky_hero.png" />
<link rel="icon" href="/icon.svg" type="image/svg+xml" /><link rel="stylesheet" href="/landing.css" /><link rel="stylesheet" href="./benchmark.css" />
</head><body class="benchmark-page">
<a class="skip-link" href="#main">Skip to content</a>
<header class="nav wrap"><a class="brand" href="/" aria-label="OmniLink home"><img src="/branding/icon/svg/mimosa.svg" width="30" height="30" alt="" />OmniLink</a><nav aria-label="Main navigation"><a href="/">Home</a><a href="/omnisim">OmniSim</a><a href="#evidence">Evidence</a></nav><a class="button button-small" href="/omnisim">Explore OmniSim ↗</a></header>
<main id="main" class="wrap">
<section class="bench-hero"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span> OmniLink in OmniSim · Development benchmark · September 24, 2026</p><h1>Robot control.<br /><span>The measured results.</span></h1><p class="bench-lead">OmniLink completed all 33 tasks in OmniSim in this run, at 45% lower model cost per successful task than the tested plain model loop. Explore every configuration, the limits of the comparison, and the evidence behind it.</p><div class="bench-tags"><span>33 tasks · 19 families</span><span>3 simulated robots</span><span>198 episodes · 6 configurations</span><span>Opus 5.5 · low effort</span></div><div class="actions"><a class="button" href="#results">See all results ↓</a><a class="text-link" href="#evidence">Verify the evidence ↗</a></div></section>
<section class="bench-block" id="results" aria-labelledby="results-title"><div class="bench-section-heading"><p class="eyebrow">01 / Completion and cost</p><h2 id="results-title">Every configuration.<br />Every attempted task.</h2><p>One run per task and configuration. These are controlled integrations built for the benchmark, rather than complete hosted products or every possible configuration of the frameworks.</p></div>
<div class="bench-results-grid"><div class="bench-chart"><h3>Model cost per successful task</h3><p class="bench-caption">USD · all attempts included · bars start at zero</p>{''.join(bars)}<p class="bench-caption">All configurations use the same model and caching policy. Shared warm-up cost is reported separately.</p></div><aside class="bench-reading"><p class="eyebrow">How to read this</p><h3>Lower model spending.<br />Completion largely tied.</h3><p>OmniLink, LangGraph, Lobster SDK, and both configurations using OmniLink command handling completed <strong>33/33</strong>. The plain loop completed <strong>32/33</strong>.</p><p>The two frameworks using OmniLink command handling matched completion at slightly lower cost than OmniLink. This supports a benefit from that component on this suite, not exclusive capability.</p><p><strong>Zero unwanted-motion episodes</strong> were observed across all 198 episodes under the sampled test criteria. This is not a safety certification or a guarantee.</p></aside></div>
<div class="bench-table-wrap" tabindex="0" role="region" aria-label="Full results table, scroll horizontally on small screens"><table><caption>Complete results · per-configuration model costs exclude shared warm-up</caption><thead><tr><th scope="col">Configuration</th><th scope="col">Completed</th><th scope="col">Failed</th><th scope="col">Unwanted motion</th><th scope="col">Model calls</th><th scope="col">Model USD</th><th scope="col">USD / success</th></tr></thead><tbody>{''.join(table)}</tbody></table></div>
<p class="bench-caption">No infrastructure errors. Total model cost: <strong>${audit['known_model_usd']:.6f}</strong>, including <strong>${audit['shared_cache_setup_usd']:.6f}</strong> for two shared cache warm-ups. All 338 paid requests have recorded usage. Model costs use provider list rates; subscriptions, hosting and local compute are excluded.</p>
<details class="bench-details"><summary>Paired estimates and uncertainty</summary><p>Cost ratio = OmniLink model cost per success ÷ comparator model cost per success; below 1 favors OmniLink. Intervals use 2,000 bootstrap draws over 19 task families, retaining robot variants together. They describe this authored suite and do not establish a market-wide ranking.</p><div class="bench-table-wrap" tabindex="0" role="region" aria-label="Paired comparison table"><table><thead><tr><th scope="col">OmniLink versus</th><th scope="col">Completion difference</th><th scope="col">Cost ratio</th><th scope="col">95% cost interval</th></tr></thead><tbody>{''.join(paired)}</tbody></table></div><p>Allocating one-sixth of warm-up to each configuration changes OmniLink to ${audit['usd_per_success_with_equal_setup_allocation']['omnilink_parser']:.5f} per success and the plain loop to ${audit['usd_per_success_with_equal_setup_allocation']['plain']:.5f}. Exact values for every configuration are in <a href="./results.json">results.json</a>.</p></details></section>
<section class="bench-block" id="method" aria-labelledby="method-title"><div class="bench-section-heading"><p class="eyebrow">02 / Method and scope</p><h2 id="method-title">Measured outcomes.<br />Shared test conditions.</h2></div><div class="bench-method-grid"><article><span class="step">TASKS</span><h3>Movement, conversation and recovery</h3><p>The 33 development tasks cover motion, pose reporting, follow-up instructions, cancellation, ambiguous and quoted commands, conditions, and injected failures. Robots: Husky, TurtleBot3 Burger and OmniArm 6. Arm grasping uses a simulator-assisted attachment.</p></article><article><span class="step">FAIR COMPARISON</span><h3>The same model and robot access</h3><p>Every configuration receives the same instructions, tools, measured state, history, controllers and safeguards. Each episode starts in a fresh simulator session. The shared limits are six planning rounds and 24 actions per operator turn.</p></article><article><span class="step">SCORING</span><h3>What the robot actually did</h3><p>Completion is based on measured positions, ordered waypoints, joint angles, object handling and required response status. A model saying “done” does not establish success. Motion is sampled at 30 ms wall intervals and tool boundaries, with explicit tolerances.</p></article><article><span class="step">COST</span><h3>All attempts count</h3><p>Cost per success includes model usage from failed tasks. All configurations use five-minute caching with common prefixes warmed before scoring. This shared-workspace cache setup does not measure isolated production cache behavior.</p></article></div>
<details class="bench-details"><summary>Exact configuration, machine and rates</summary><p>Model: <code>claude-opus-5-5</code>, direct Anthropic API, low effort, standard tier, 2,048 maximum output tokens including thinking. No paid-request retries. Rates per million tokens: ordinary input $4, output $20, five-minute cache writes $5 and cache reads $0.20. Usage is derived from returned counters, not reconciled to an invoice.</p><p>Machine: Windows 11; AMD64 Family 25 Model 80, 16 logical processors; NVIDIA RTX 3060 Laptop GPU. Physics used Newton 1.5.0 / MuJoCo 3.11.0 on CPU; GPU acceleration was not used for benchmark physics. Machine fingerprint: <code>9722d23d12a3</code>. Python 3.12.14; Node 22.19.0; LangGraph 1.2.12; pinned Lobster SDK commit <code>71bd8145055498116de35623dbea0d7dda9b4cd5</code>. Complete hashes are in the archived lock.</p><p>Order was shuffled with fixed seed 240926. The suite and configuration were frozen before this campaign. The tasks were previously seen during development; they are not an independent holdout. OmniLink names the tested agent-control integration; OmniSim is the simulator used for every configuration. This does not measure every feature of either product.</p><p>LangGraph uses its actual graph runtime; Lobster uses its actual SDK pipeline. Their planning/execution callbacks share benchmark logic. The two “+ OmniLink command handling” configurations are component-sharing controls. Exact mappings to the original record identifiers are in <a href="./results.json">results.json</a>; evidence and source are preserved without relabeling.</p></details>
<div class="bench-notice"><h3>The one failed episode</h3><p>The plain model loop did not finish a TurtleBot3 conversation task. It requested clarification instead of executing the final instructed motion after detecting a small earlier position discrepancy. The frozen completion criteria marked it failed. No unwanted motion was observed. The episode remains in every denominator and in the raw evidence.</p></div>
<p class="bench-caption">This developer-authored suite contains one repeat per task. It excludes vision-based navigation, fleet coordination, autonomous exploration and physical hardware. Sampled “no unwanted motion” observations are not continuous safety monitoring. The results establish neither superiority over all competitors nor a general capability lead.</p></section>
<section class="bench-block" id="evidence" aria-labelledby="evidence-title"><div class="bench-section-heading"><p class="eyebrow">03 / Evidence and reproduction</p><h2 id="evidence-title">Inspect it.<br />Verify the recorded results.</h2><p>The evidence archive preserves raw responses, provider usage, simulator observations, physics logs, task definitions, frozen source and the verification program. All 198 grades and 1,143 file hashes passed offline verification.</p></div><div class="bench-downloads"><a class="bench-download" href="./evidence.zip" download><span class="step">PRIMARY EVIDENCE · 14.4 MB</span><strong>Download the full run <span aria-hidden="true">↓</span></strong><span>Raw records, source snapshots and offline verifier</span></a><a class="bench-download" href="./development-history.zip" download><span class="step">DEVELOPMENT HISTORY · 20.1 MB</span><strong>Inspect earlier attempts <span aria-hidden="true">↓</span></strong><span>Earlier campaigns, failures and the interrupted uncached run</span></a></div>
<div class="bench-verify"><h3>Verify offline with Python 3.12</h3><p>Extract <code>evidence.zip</code> into a new folder, open a terminal there, and run:</p><pre><code>python -I -S verify_archive.py</code></pre><p>No API key, network, simulator or paid call is needed. The verifier recomputes grades and costs from saved observations and checks archive hashes. Hashes establish consistency; this is not independent validation of the original run.</p><div class="bench-evidence-links"><a href="./SHA256SUMS.txt">Archive SHA-256 checksums ↗</a><a href="./OFFLINE_VERIFICATION.json">Verification output ↗</a><a href="./results.json">All results as JSON ↗</a><a href="./MATCHED_COMPARISON.md">Technical report ↗</a><a href="./REPRODUCE.md">Reproduction instructions ↗</a><a href="./SPEC.md">Scoring specification ↗</a></div></div>
<div class="bench-notice"><h3>A fresh live run needs the matching release</h3><p>Offline verification is available now. Running the robots and model again requires the matching OmniSim 9.0.0 Windows runtime, source, assets and pinned dependencies, plus your own OmniKey and Anthropic API key. The archive omits the engine binaries; public availability of the exact matching release has not been verified. Do not substitute an older public build or assume a version number alone guarantees a match. Check the archived hashes. Live runs incur provider charges and may differ as the hosted model changes.</p></div>
<details class="bench-details"><summary>Earlier campaigns and why this run is separate</summary><p>The earlier Gemini campaign completed 198 episodes with 32/33 completions and one unwanted-motion episode for every configuration. It used a different model transport and prompt wrapper, so it is historical evidence rather than a controlled model-only comparison.</p><p>An uncached Opus run was stopped at the owner's request to prepare this cached comparison: 101 completed episodes, $3.397460 in known request costs, plus one unresolved in-flight reservation of up to $0.085648. It is incomplete and is not pooled with this run. The cached run started from a new frozen campaign and completed all planned episodes. Earlier pilots and failures are retained in the history archive; any privacy redactions are listed with original and exported hashes.</p><p>The campaign protocol's “prepared, not started” wording records its pre-run state. It is retained unchanged; completed results and timestamps are in the final evidence. Historical report statements about no deployment describe the measurement/export step, not the publication status of this website.</p></details></section>
<section class="bench-block bench-next"><p class="eyebrow">Next research milestone · planned</p><h2>Reliable completion<br />when conditions change.</h2><p>Our next step is a harder, independently reviewed evaluation of recovery from disturbances and partial execution, using unfamiliar tasks and strong complete-system baselines. That work is planned; no capability result is claimed here.</p><a class="text-link" href="/omnisim">Explore OmniSim ↗</a></section>
</main><footer class="footer wrap"><a class="brand" href="/">OmniLink<span class="brand-dot">.</span></a><p>© OmniLink 2026</p><nav aria-label="Footer"><a href="/">Home</a><a href="/omnisim">OmniSim</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav></footer></body></html>'''
    page = page.replace('src="/branding/icon/svg/mimosa.svg"', 'src="/icon.svg"')
    write(base + 'index.html', page)
    write(base + 'benchmark.css', CSS)
    seo = (SITE / 'src/seo.ts').read_text(encoding='utf-8')
    seo = seo.replace('OmniSim Robotics Control Benchmarks | OmniLink', 'OmniLink Robotics-Control Benchmarks')
    seo = seo.replace('Inspect OmniSim robotics-control results:', 'Inspect OmniLink robotics-control results in OmniSim:')
    marker = '  // ── Legal / trust'
    entry = '''  {
    file: 'public/benchmarks/robotics-control/index.html',
    path: '/benchmarks/robotics-control/index.html',
    title: 'OmniLink Robotics-Control Benchmarks',
    description:
      'Inspect OmniLink robotics-control results in OmniSim: 33 tasks, six configurations, measured completion, model costs, full evidence and offline verification.',
  },

'''
    assert marker in seo
    write('src/seo.ts', seo if "file: 'public/benchmarks/robotics-control/index.html'" in seo else seo.replace(marker, entry + marker))
    print(json.dumps({'staging': str(OUT), 'cost_reduction_percent': reduction,
                      'files': [str(f.relative_to(OUT)) for f in OUT.rglob('*') if f.is_file()]}))


CSS = '''/* Verified robotics benchmark presentation; no runtime data fetching. */
.robotics-benchmark{scroll-margin-top:32px}.benchmark-heading{display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:end}.benchmark-heading .eyebrow{margin-bottom:22px}.benchmark-heading h2 span{color:var(--accent)}.benchmark-heading>p{max-width:440px;color:var(--muted);font-size:15px}.benchmark-kpis{display:grid;grid-template-columns:1fr 1fr 1.15fr;border:1px solid var(--line);border-radius:10px;margin:36px 0 28px;background:#191c15;overflow:hidden}.benchmark-kpis article{padding:28px;border-right:1px solid var(--line)}.benchmark-kpis article:first-child{background:#232719}.benchmark-kpis article:last-child{border:0}.benchmark-label{color:#d6d9cb;font-size:12px;min-height:40px}.benchmark-number{font-size:72px;letter-spacing:-3px;line-height:1.2;font-weight:500;color:var(--accent);margin:12px 0 16px;font-variant-numeric:tabular-nums}.benchmark-number span{font-size:36px;color:#d6d9cb;letter-spacing:-1px}.benchmark-number.benchmark-price{font-size:54px;line-height:1.6;letter-spacing:-2px;color:#f5f4ed}.benchmark-kpis article>p:last-child{font-size:12px;color:var(--muted)}.benchmark-takeaway{display:flex;gap:36px;align-items:center;justify-content:space-between}.benchmark-takeaway p{max-width:720px;font-size:14px;color:#c9ccbf}.benchmark-takeaway strong{color:#f5f4ed}.benchmark-scope{font-size:12px;color:var(--muted);line-height:1.75;margin-top:18px;max-width:1080px}
.bench-hero{padding:72px 0 58px}.bench-hero h1{margin-top:25px;max-width:950px}.bench-lead{max-width:790px;color:#ced0c5;font-size:18px;margin-top:28px}.bench-tags{display:flex;flex-wrap:wrap;gap:10px;margin:28px 0}.bench-tags span{font-size:11px;border:1px solid #424638;border-radius:30px;padding:8px 13px;color:#c5c9b9}.bench-block{padding:65px 0;border-top:1px solid var(--line);scroll-margin-top:25px}.bench-section-heading{max-width:860px}.bench-section-heading .eyebrow,.bench-next .eyebrow{margin-bottom:22px}.bench-section-heading>p:last-child:not(.eyebrow){margin-top:22px;color:var(--muted);font-size:15px}.bench-results-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:46px;margin:38px 0}.bench-chart{padding:28px;border:1px solid var(--line);border-radius:10px;background:#191c15}.bench-chart h3,.bench-reading h3{font-size:19px;font-weight:500;line-height:1.4}.bench-caption{font-size:12px;color:var(--muted);line-height:1.75;margin-top:14px}.bench-bar-row{margin-top:23px}.bench-bar-label{display:flex;justify-content:space-between;gap:15px;font-size:12px;line-height:1.6}.bench-bar-label strong{font-variant-numeric:tabular-nums;font-weight:500;white-space:nowrap}.bench-bar-track{height:9px;background:#303429;border-radius:3px;overflow:hidden;margin-top:8px}.bench-bar-track>div{height:100%;background:#919b80;border-radius:3px}.is-omnisim .bench-bar-track>div{background:var(--accent)}.is-omnisim .bench-bar-label{color:var(--accent)}.bench-reading{padding:10px 0}.bench-reading h3{font-size:27px;letter-spacing:-.7px;margin:20px 0}.bench-reading>p:not(.eyebrow){font-size:14px;color:#c5c9b9;margin-top:18px}.bench-table-wrap{max-width:100%;overflow:auto;border:1px solid var(--line);border-radius:8px;margin:26px 0 12px}.bench-table-wrap:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.benchmark-page table{border-collapse:collapse;width:100%;font-size:12px;font-variant-numeric:tabular-nums}.benchmark-page caption{text-align:left;padding:18px;background:#1a1d16;color:#c3c8b6;line-height:1.6}.benchmark-page th,.benchmark-page td{text-align:right;padding:16px 18px;border-top:1px solid var(--line);white-space:nowrap}.benchmark-page th:first-child{text-align:left;white-space:normal;min-width:210px;line-height:1.6}.benchmark-page thead th{font-size:11px;font-weight:500;color:#b2b8a6;background:#191c15}.benchmark-page tbody th{font-weight:500}.benchmark-page tr.is-omnisim{background:#232719;color:#eadd78}.bench-details{border-top:1px solid var(--line);padding-top:20px;margin-top:28px}.bench-details summary{cursor:pointer;font-size:14px;color:#e1e3d8;line-height:1.6}.bench-details>p{margin-top:18px;max-width:970px;font-size:14px;color:var(--muted)}.benchmark-page p a,.bench-evidence-links a{color:var(--accent);text-decoration:underline;text-underline-offset:4px}.bench-method-grid{display:grid;grid-template-columns:1fr 1fr;gap:40px 65px;margin-top:38px}.bench-method-grid h3{font-size:19px;font-weight:500;margin:16px 0 12px}.bench-method-grid p{font-size:14px;color:var(--muted)}.bench-notice{border-left:3px solid #b9af65;background:#1b1e16;padding:24px 28px;margin-top:28px}.bench-notice h3{font-size:16px;font-weight:550;margin-bottom:10px}.bench-notice p{font-size:14px;color:#c0c6b3;max-width:970px}.bench-downloads{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:30px 0}.bench-download{display:flex;flex-direction:column;gap:14px;padding:27px;border:1px solid #62684e;border-radius:9px;background:#1c2017;transition:border-color .15s}.bench-download:hover{border-color:var(--accent)}.bench-download strong{display:flex;justify-content:space-between;font-size:21px;font-weight:500;gap:20px}.bench-download>span:last-child{font-size:12px;color:var(--muted)}.bench-verify{padding:28px;border:1px solid var(--line);border-radius:9px}.bench-verify h3{font-size:19px;font-weight:500}.bench-verify p{font-size:14px;color:var(--muted);margin-top:18px}.benchmark-page pre{overflow:auto;background:#0d0f0b;padding:20px;border-radius:6px;font-size:14px;margin:20px 0;color:#e1d256}.benchmark-page code{overflow-wrap:anywhere;font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.bench-evidence-links{display:flex;flex-wrap:wrap;gap:18px 25px;margin-top:24px;font-size:12px}.bench-next>p:not(.eyebrow){margin-top:24px;max-width:800px;color:var(--muted)}
@media(max-width:1050px){.benchmark-kpis article{padding:23px}.benchmark-number{font-size:62px}.benchmark-number.benchmark-price{font-size:44px}.benchmark-heading{gap:30px}.benchmark-takeaway{align-items:flex-start;flex-direction:column;gap:20px}.bench-results-grid{gap:28px;grid-template-columns:1.1fr 1fr}.bench-chart{padding:22px}.bench-bar-label{font-size:11px}}
@media(max-width:700px){.benchmark-heading{display:block}.benchmark-heading>p{margin-top:22px;font-size:14px}.benchmark-kpis{grid-template-columns:1fr;margin-top:28px}.benchmark-kpis article{padding:24px;border-right:0;border-bottom:1px solid var(--line)}.benchmark-label{min-height:0}.benchmark-number{font-size:64px;margin:12px 0}.benchmark-number.benchmark-price{font-size:54px;line-height:1.2}.benchmark-scope{font-size:12px}.bench-hero{padding:45px 0 35px}.bench-hero h1{font-size:46px;letter-spacing:-2.8px}.bench-lead{font-size:15px}.bench-block{padding:43px 0}.bench-results-grid,.bench-method-grid,.bench-downloads{grid-template-columns:1fr}.bench-results-grid{gap:24px}.bench-chart{padding:22px 18px}.bench-bar-label{font-size:12px}.bench-reading{padding:0}.bench-reading h3{font-size:24px}.bench-method-grid{gap:30px}.bench-download{padding:23px}.bench-download strong{font-size:19px}.bench-notice,.bench-verify{padding:22px 18px}.benchmark-page pre{font-size:12px;padding:16px}.bench-tags{gap:8px}.bench-tags span{font-size:10px}.bench-section-heading>p:last-child:not(.eyebrow){font-size:14px}.benchmark-page .nav nav{gap:14px}.benchmark-page .bench-evidence-links{gap:18px}}
@media(prefers-reduced-motion:reduce){.bench-download{transition:none}}
'''

